":"Uncommon","minimum":10,"maximum":49},{"id":"Rare","minimum":50,"maximum":99},{"id":"Epic","minimum":100,"maximum":999},{"id":"Legendary","minimum":1000,"maximum":9999},{"id":"Mythic","minimum":10000,"maximum":99999},{"id":"Exotic","minimum":100000,"maximum":999999},{"id":"Exalted","minimum":1000000,"maximum":9999999},{"id":"Cosmic","minimum":10000000,"maximum":99999999},{"id":"Transcendent","minimum":100000000,"maximum":999999999}],"catalogue":{"approved":false,"entries":[],"proposal":"shared Common/Uncommon/Rare; destination-exclusive higher tiers require separate approval"},"quest":{"id":"call-of-the-abyss","panel":"Unidentified Transmission","enabled":false,"prerequisites":{"lifetimeField":"players.total_rolls","minimumLifetimeRolls":250000,"craftPickaxeMinimumTier":12,"craftEvidence":"successful server crafting transaction; ownership/history of ownership is insufficient; never infer absent evidence"},"stages":[{"stage":1,"kind":"specimen","gem":"Quartz","mutations":"all attached mutation IDs must be empty","measurement":"ordinaryFinalWeightRatio=ordinary finalWeight/baseWeight BEFORE Abyssal Laws, including ordinary equipment/size/masterwork/storage factors","comparison":"<","threshold":1,"zeroBaseWeight":"ineligible"},{"stage":2,"kind":"specimen","measurement":"rawRolledWeightMultiplier=R before final equipment/size/law factors","comparison":">","threshold":5},{"stage":3,"kind":"specimen","gem":"Black Opal","requiredMutation":"glossy","allowOtherMutations":true},{"stage":4,"kind":"sale","eligibleProceeds":5000000,"eligibility":"eligible sales of newly accepted genuine primary specimens acquired after stage activation; persist actual credited proceeds and deduplicate sale transaction; reject old stock and bonus credit; NPC-only versus market eligibility must be frozen before Phase2 quest activation"},{"stage":5,"kind":"genuine_rolls","world":1,"count":3000},{"stage":6,"kind":"explicit_action","action":"Begin Descent","automatic":false}],"activation":"sequential; record timestamp and accepted sequence high-water mark; no retroactive credit; failed attempts and extras excluded"},"histories":{"world":2,"positions":250,"genuineOnly":true,"includeEmptyRelicAndLoss":true,"bonusCredit":false,"persistAcrossEpochsAndVisits":true,"mutationHistoryAlwaysUpdates":true,"gemFormula":"s_i=max(floor,exp(-k*count_i)); normalize final-winning mutable band mass, never sequential hazards","baseline":{"k":0.05,"floor":0.75}},"adaptation":{"enabled":false,"provisional":true,"directions":[[1,2],[2,1]],"levels":[{"level":0,"factor":0.5,"qualifyingRolls":0},{"level":1,"factor":0.55,"qualifyingRolls":2500},{"level":2,"factor":0.6,"qualifyingRolls":7500},{"level":3,"factor":0.65,"qualifyingRolls":20000},{"level":4,"factor":0.7,"qualifyingRolls":45000},{"level":5,"factor":0.75,"qualifyingRolls":100000}],"credit":"accepted genuine outcome with opposite-native equipped pickaxe; no extra specimens; no retroactive inference from lifetime counter","scope":["pickaxe","clover","lantern","boots","bag"],"petGear":"separate pet-odds contract; blocked","rollBulk":"integer capacity unchanged","legacyNativeWorld":1,"unknownEquipment":"fail closed for cross-world compatibility; never generic fallback"},"state":{"temporaryLaw":"reset on new epoch; histories persist; repeated laws still reset epoch state","outsideWorld2":"genuine counters freeze","equipment":"separate world counters/queues; preserve native equipment-switch reset rules; resolve adaptation level when applying effect","momentum":"single account resource in deployed convergence_private; never duplicate","surge":"single activation world; remaining genuine rolls advance there only","blessing":"single activation world; five minute real-time expiry; no pause/reset on switching"},"outcomeContract":{"phase":2,"lockOrder":["players row","world2 player state","world buckets/law history","inventory/routing resources in canonical order"],"identity":["player_id","request_id","subroll"],"request":"server authenticated player; canonical request digest; changed payload under same request ID rejected","batch":"DB claim pins world, epoch/version and state revision AFTER lock; whole accepted batch same tuple","deadline":"must finalize before accepted lease expires; expired/replaced lease is fenced, never silently recalculate RNG","boundary":"preclaim context crossing epoch must recompute speed before acceptance","retry":"lookup immutable receipt before any RNG or mutation; committed retry returns same outcome","partial":"committed prefix survives once; uncommitted suffix requires a new claim/request; never replay committed RNG","atomic":"specimen routing, actual payout, total_rolls increment, internal fence, world genuine ordinal, history, law state and receipt commit together; failures abort","noSpecimen":"accepted House Edge loss/empty/relic advances genuine position exactly once","worldSwitch":"serialize on players lock; reject while lease active; preserve histories/buckets/timers","reconnect":"read state only; never initialize-overwrite existing state","phase1":"no claim/commit/switch/gameplay endpoint implemented"},"provenance":{"legacyDefault":{"originWorld":1,"npcLiquidationFactor":1},"immutable":true,"noStoredValueRewrite":true,"npcFactor":0.8,"p2pCashTax":false,"phase":4,"sources":["roll primary","Astral duplicate","Breakneck bonus","Convergence package","inventory insert/restore","NPC manual/bulk/auto sale","auction listing/buy/settle/cancel/expire/relist","Black Market","gem orders","museum","reward/admin/shop/legacy"],"transport":"future stable specimen UUID alongside every reconstruction; absent metadata neutral legacy W1; never synthesize current law at sale","privacy":"acquisition owner is not current owner; provenance table service-only, future read via ownership-checked inventory joins"},"unresolvedGameplayDetails":["World 2 catalogue and source memberships remain unapproved","Pet-odds adaptation is deferred","Phase 3 transition implementation must freeze inclusive sampling and exact tick/trigger ordering before activation","Crafting proof availability must be evaluated per transaction; no ownership-based backfill","Stage4 eligible sale channels and provenance for non-primary rewards require explicit activation contract; no sale credit in Phase1"],"equipmentCompatibility":{"attachedEffects":[{"id":"deep_strike","type":"stateful_multiplier","layer":"enchant Luck","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"normal every7th x1.35; ancient every5th x1.5; compose strengthening then F","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"fortune_surge","type":"stateful_multiplier","layer":"enchant Luck","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"5%/8% activates NEXT3 x1.35/1.5; no active retrigger; compose strengthening then F","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"collectors_edge","type":"conditional_multiplier","layer":"enchant Luck","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"F(1+.12*c) / F(1+.25*c); destination discovery denominator must be approved; optional-biome exclusions","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"prospectors_instinct","type":"stateful_multiplier","layer":"enchant Luck","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"raw>=5000/10000 refills NEXT4/6 x1.4/1.6; compose strengthening then F","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"vein_hunter","type":"stateful_multiplier","layer":"enchant Luck","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"miss<=30; F(1+miss/100); raw>=10000 resets; distinct from Astral duplicate","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"jackpot_mining","type":"random_multiplier","layer":"enchant Luck","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"keep 8% positive x1.75/2.5 then next4% x.5; F positive strengthened factor; full loss","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"blitz_vein","type":"stateful_multiplier","layer":"WL Speed WM","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"every20/10 stack cap10; nonrelic raw>=30000 resets; compose strengthening then F","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"slow_starter","type":"cooldown_factor","layer":"cooldown","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"ancient branch only max(.5,1.75-.025*r); c<1 ->1-a*(1-c); preserve c>=1 slowing","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"geologist","type":"candidate_multiplier","layer":"candidate Luck","neutralBaseline":1,"eligibility":"undiscovered eligible gem","counterDomain":"world bucket","adaptationPolicy":"F(strengthened1.5)","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"lucky_break","type":"reroll_opportunity","layer":"gem identity","neutralBaseline":0,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"5%*a / 10%*a; whole higher-raw-rarity comparison; weight/mutations sampled once","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"steady_hand","type":"final_weight","layer":"masterwork","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"F(1.03/1.05)","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"careful_extraction","type":"conditional_multiplier","layer":"masterwork final weight","neutralBaseline":1,"eligibility":"raw>=100000","counterDomain":"world bucket","adaptationPolicy":"F(1.10/1.15)","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"mutation_resonance","type":"natural_mutation","layer":"masterwork","neutralBaseline":1,"eligibility":"native eligibility unchanged","counterDomain":"world bucket","adaptationPolicy":"F(1.05/1.08)","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]},{"id":"deep_survey","type":"candidate_multiplier","layer":"masterwork candidate Luck","neutralBaseline":1,"eligibility":"raw>=100000","counterDomain":"world bucket","adaptationPolicy":"F(1.05/1.08)","rewardProvenance":"same acquisition world; extras link primary receipt; no genuine/lifetime/adaptation credit","exceptions":[]}],"attachedContract":"follow owning equipment native world; compose enchant/conduit/attunement once; preserve old-item masterwork fallback; All-In suppression unchanged","unknownPolicy":"reject cross-world compatibility; legacy native identity defaults W1 only"}}'::jsonb);
